verus! {
    pub fn is_sorted(arr: &Vec<i32>) -> (result: bool)
        requires
            arr.len() > 0,
        ensures
            result == (forall|i: int, j: int| 0 <= i < j < arr.len() ==> (arr[i] <= arr[j])),
    {
        // Initialize the result to true
        let mut res = true;

        // Iterate through the array to check the sorting condition
        let n = arr.len();
        // We will check pairs (i, j) where 0 <= i < j < n
        // This can be done with a nested loop
        for i in 0..n {
            // We need to ensure that we only check j > i
            for j in (i + 1)..n {
                // If we find any pair where arr[i] > arr[j], set res to false
                if arr[i] > arr[j] {
                    res = false;
                }
            }
        }

        // Return the result
        res
    }
}